    ListNode dummy{0, nullptr};
    ListNode* tail = &dummy;
    int carry = 0;
    while (a || b || carry) {
        int sum = carry;
        if (a) { sum += a->val; a = a->next; }
        if (b) { sum += b->val; b = b->next; }
        tail->next = new ListNode{sum % 10, nullptr};
        tail = tail->next;
        carry = sum / 10;
    }
    return dummy.next;
}

